<script lang="ts">
 import {onMount} from 'svelte';
 import {startRegistration,startAuthentication} from '@simplewebauthn/browser';
 import Button from './components/Button.svelte';import List from './components/List.svelte';import Row from './components/Row.svelte';import Cover from './components/Cover.svelte';import Sheet from './components/Sheet.svelte';import StepDots from './components/StepDots.svelte';import WeekDots from './components/WeekDots.svelte';import TabBar from './components/TabBar.svelte';import Keyboard from './components/Keyboard.svelte';import VerseText from './components/VerseText.svelte';
 import {tokenize,firstLetters,maskWords,allowance,grade,transition,schedule,gentleCap,dueItems} from './engine';
 import {starters,documents,lookupReference} from './content';
 import {openStore,persist,api,mergeItems,defaults,today,type LocalState,type Item} from './store';
 let data=$state<LocalState>({items:[],events:[],settings:{...defaults},queue:[]});
 let ready=$state(false),tab=$state('Today'),detail=$state(''),practice=$state<Item|null>(null),session=$state<string[]>([]),position=$state(0),slips=$state<number[]>([]),result=$state(false),learned=$state(false),shortcut=$state(false),review=$state(false),message=$state(''),error=$state(''),busy=$state(false),account=$state<any>(null),config=$state<any>({}),recovery=$state(''),recoverInput=$state(''),confirmDelete=$state(false),welcome=$state(false),addMode=$state('verse'),reference=$state(''),translation=$state('BSB'),customTitle=$state(''),customText=$state(''),found=$state<any[]>([]),selectedDoc=$state(''),nextDue=$state('');
 const live=$derived(data.items.filter(i=>!i.deleted));
 const daysAway=$derived(data.settings.lastActive?Math.floor((Date.now()-new Date(data.settings.lastActive+'T12:00:00').getTime())/86400000):0);
 const rampDay=$derived(data.settings.returnStart?Math.floor((Date.now()-new Date(data.settings.returnStart+'T12:00:00').getTime())/86400000):7);
 const cap=$derived(gentleCap(data.settings.returnStart&&rampDay<7?7:daysAway,rampDay,12));
 const due=$derived(dueItems(live,new Date(),{daysAway:data.settings.returnStart&&rampDay<7?7:daysAway,rampDay,normal:12}));
 const words=$derived(practice?tokenize(practice.text):[]);
 const mask=$derived(practice?maskWords(practice.text,review?4:practice.step):[]);
 const hidden=$derived(mask.filter(Boolean).length);
 const collection=$derived(starters.find((s:any)=>s.id===detail));
 const detailItems=$derived(live.filter(i=>i.collection===detail));
 const weekCount=$derived(data.settings.days.filter(d=>{const date=new Date(d+'T12:00:00');const now=new Date();now.setDate(now.getDate()-((now.getDay()+6)%7));now.setHours(0,0,0,0);return date>=now}).length);
 function theme(){document.documentElement.dataset.theme=data.settings.theme}
 async function save(){data.settings.updatedAt=Date.now();await persist($state.snapshot(data));theme();if(account)void sync()}
 async function sync(){try{const out=await api('/sync',{items:$state.snapshot(data.items),events:$state.snapshot(data.events),settings:$state.snapshot(data.settings)});data.items=mergeItems(data.items,out.items||[]);if(out.settings&&Number(out.settings.updatedAt)>data.settings.updatedAt)data.settings={...defaults,...out.settings};theme();const map=new Map(data.events.map(e=>[e.id,e]));for(const e of out.events||[])map.set(e.id,e);data.events=[...map.values()];data.queue=[];await persist($state.snapshot(data));message='All changes saved.'}catch(e){message='Saved on this device. Sync will resume online.'}}
 async function attempt(fn:()=>Promise<void>){busy=true;error='';try{await fn()}catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
 onMount(()=>{void attempt(async()=>{data=await openStore();data.settings={...defaults,...data.settings};ready=true;theme();welcome=daysAway>=7&&rampDay>=7;try{config=await api('/config');const out=await api('/me');account=out.user||out.account||null;if(out.recoveryCode)recovery=out.recoveryCode;if(account)await sync()}catch{} });const online=()=>{if(account)void sync()};window.addEventListener('online',online);return()=>window.removeEventListener('online',online)});
 function navigate(to:string){tab=to;detail='';error='';message=''}
 async function add(items:any[],collectionId?:string){for(const item of items){if(!live.some(i=>i.id===item.id))data.items.push({...item,collection:collectionId||item.collection||'personal',step:1,learned:false,due:new Date().toISOString(),updatedAt:Date.now()})}data.queue.push(crypto.randomUUID());await save();message='Added to your library.'}
 async function addStarter(s:any){await add(s.items,s.id);detail=s.id;tab='Library'}
 function begin(items:Item[]){session=items.map(i=>i.id);loadNext()}
 function loadNext(){const id=session.shift();if(!id){practice=null;learned=false;result=false;return}const item=data.items.find(i=>i.id===id)!;practice=item;review=item.learned;shortcut=false;learned=false;position=0;slips=[];result=false;nextDue=''}
 function key(key:string,peek=false){if(!practice||result||learned||position>=words.length)return;const wrong=peek||!firstLetters(words[position]).includes(key.toLowerCase());if(wrong&&mask[position])slips.push(position);position++;if(position>=words.length)result=true}
 function physical(e:KeyboardEvent){if(practice&&!result&&!learned&&!e.metaKey&&!e.ctrlKey&&!e.altKey&&/^[a-z0-9]$/i.test(e.key)){e.preventDefault();key(e.key)}}
 async function finish(){if(!practice)return;const now=new Date();const g=grade(slips.length,hidden);const out=transition(practice.step,slips.length,hidden,shortcut);if(review){const scheduled=schedule(practice.card,g,now);practice.card=scheduled.card;practice.due=new Date(scheduled.card.due).toISOString();nextDue=new Date(practice.due).toLocaleDateString(undefined,{month:'short',day:'numeric'});if(g==='Again'){practice.learned=false;practice.step=3;review=false}else{learned=true}}else{practice.step=out.step;practice.learned=out.learned;if(out.learned){const scheduled=schedule(undefined,g,now);practice.card=scheduled.card;practice.due=new Date(scheduled.card.due).toISOString();nextDue=new Date(practice.due).toLocaleDateString(undefined,{month:'short',day:'numeric'});learned=true}}
 practice.updatedAt=Date.now();const event={id:crypto.randomUUID(),itemId:practice.id,at:now.toISOString(),slips:slips.length,hidden,grade:g};data.events.push(event);data.queue.push(event.id);if(!data.settings.days.includes(today()))data.settings.days.push(today());data.settings.lastActive=today();await save();result=false;position=0;slips=[];shortcut=false}
 async function signup(){await attempt(async()=>{const options=await api('/auth/register/options',{displayName:data.settings.name});const response=await startRegistration({optionsJSON:options.options||options});const out=await api('/auth/register/verify',{response,name:data.settings.name});account=out.user||out.account;recovery=out.recoveryCode||'';await sync()})}
 async function signin(){await attempt(async()=>{const options=await api('/auth/login/options',{});const response=await startAuthentication({optionsJSON:options.options||options});const out=await api('/auth/login/verify',{response});account=out.user||out.account;await sync()})}
 async function recover(){await attempt(async()=>{const out=await api('/auth/recover',{code:recoverInput});account=out.user||out.account;recovery=out.recoveryCode||'';recoverInput='';await sync()})}
 async function signout(){await attempt(async()=>{await api('/auth/logout',{});account=null;message='Signed out. Your practice stays on this device.'})}
 async function exportData(){await attempt(async()=>{const out=account?await api('/export'):$state.snapshot(data);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}));a.download='by-heart.json';a.click();URL.revokeObjectURL(a.href);message='Your export is ready.'})}
 async function deleteAccount(){await attempt(async()=>{await api('/account',undefined,'DELETE');account=null;confirmDelete=false;message='Account deleted. Local practice is still on this device.'})}
 async function enablePush(){await attempt(async()=>{if(!account)throw Error('Sign in to enable reminders.');if(!('Notification'in window)||!('PushManager'in window))throw Error('On iPhone, add By Heart to your Home Screen first, then open it there.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notifications were not enabled. You can change this in your browser settings.');const reg=await navigator.serviceWorker.ready;const raw=config.vapidPublicKey||config.vapid; if(!raw)throw Error('Reminders will be available when the server VAPID key is configured.');const key=Uint8Array.from(atob(raw.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));const sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});await api('/push/subscribe',{subscription:sub.toJSON()});data.settings.pushEnabled=true;await save();message='Gentle reminders enabled.'})}
 async function disablePush(){await attempt(async()=>{const reg=await navigator.serviceWorker.ready;await (await reg.pushManager.getSubscription())?.unsubscribe();await api('/push/subscribe',{subscription:null});data.settings.pushEnabled=false;await save()})}
 async function search(){await attempt(async()=>{found=await lookupReference(reference,translation);if(!found.length)throw Error('No verses found. Try a reference such as Romans 8:28-30.')})}
 async function own(){await attempt(async()=>{if(!customTitle.trim()||!customText.trim())throw Error('Add a title and some text.');await add([{id:crypto.randomUUID(),title:customTitle.trim(),text:customText.trim(),collection:'personal'}]);customTitle='';customText='';navigate('Library')})}
 function know(){if(practice){practice.step=4;shortcut=true;position=0;slips=[]}}
 function restart(){position=0;slips=[];result=false}
 async function remove(item:Item){item.deleted=true;item.updatedAt=Date.now();await save()}
</script>
<svelte:window onkeydown={physical}/>
<main>
{#if !ready}<section class="empty"><h1>By Heart</h1><p>A little practice. A lasting word.</p></section>
{:else if practice}
 {#if learned}<section class="learned"><div class="keepsake" aria-hidden="true">♡</div><small>{review?'A little stronger.':'Yours to keep.'}</small><h1>{review?'Remembered.':'Learned.'}</h1><h2>{practice.title}</h2><p>{review?'A word worth returning to.':'Not just on a page. In your heart.'}</p>{#if nextDue}<small>Next review · {nextDue}</small>{/if}<Button onclick={loadNext}>{session.length?'Next item':'Back to Today'}</Button><Button secondary onclick={()=>{learned=false;practice!.learned=false;practice!.step=1;review=false;restart()}}>Practice again</Button></section>
 {:else}<section class="practice"><header><button class="icon" aria-label="Close practice" onclick={()=>practice=null}>×</button><StepDots step={review?4:practice.step}/>{#if practice.step===1&&!review}<Button secondary onclick={know}>I know this</Button>{:else}<button class="icon" aria-label="Restart step" onclick={restart}>↻</button>{/if}</header><div class="prompt"><small>{review?'Review · blank recall':'Step '+practice.step+' of 4 · '+['','Read along','A few words hidden','Almost from memory','From the heart'][practice.step]}</small><h1>{practice.title}</h1><small>{practice.translation||'By Heart · '+practice.collection}</small></div><div class="progress"><i style:width={position/words.length*100+'%'}></i></div><VerseText {words} {mask} index={position} slipped={slips}/><Keyboard onkey={key} onpeek={()=>key('',true)} disabled={result}/></section>{/if}
 {#if result}<Sheet title={review?grade(slips.length,hidden):slips.length<=allowance(hidden)?'Beautifully done.':'A little more practice.'}><p>{slips.length} {slips.length===1?'slip':'slips'} · {hidden} hidden words. {review?'Let’s give this word room to settle.':slips.length<=allowance(hidden)?'Ready for the next small step.':'Stay here as long as you need.'}</p><Button onclick={()=>void finish()}>{review?'Save review':slips.length<=allowance(hidden)?practice.step===4?'Keep it by heart':'Continue':'Try again'}</Button><Button secondary onclick={()=>practice=null}>Close practice</Button></Sheet>{/if}
{:else}
 <section class="page" class:account={tab==='Account'}>
 <header><div><h1>{detail?collection?.title||'Your own words':tab==='Account'?'Your space':tab==='Gallery'?'Components':tab}</h1><p>{tab==='Today'?'A little practice. A lasting word.':tab==='Library'?'Good words, close at hand.':tab==='Discover'?'Find something worth keeping.':'By Heart'}</p></div><button class="icon" aria-label={detail?'Back to library':'Account settings'} onclick={()=>detail?detail='':navigate('Account')}>{detail?'‹':data.settings.name.slice(0,1).toUpperCase()||'◌'}</button></header>
 {#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if message}<div class="notice" role="status">{message}</div>{/if}
 {#if tab==='Today'}
 <div class="rhythm"><div><b>{weekCount} of {data.settings.goal} days this week</b><small>A rhythm, not a streak.</small></div><WeekDots days={data.settings.days}/></div>
 {#if due.length}<div class="hero"><div><b>{due.length} little steps</b><small>About {Math.max(1,Math.ceil(due.length*1.5))} minutes · just for today</small></div><Button onclick={()=>begin(due)}>Begin</Button></div><h3 class="section-title">For today</h3><List>{#each due as item}<Row title={item.title} subtitle={item.learned?'Review':item.collection} onclick={()=>begin([item])}><StepDots step={item.learned?5:item.step}/></Row>{/each}</List>
 {:else}<div class="empty"><div class="heart">♡</div><h2>{live.length?'Done for today.':'Start with a word.'}</h2><p>{live.length?'Let these words stay with you. Come back when you’re ready.':'Choose a small collection and make it yours.'}</p><Button onclick={()=>navigate('Library')}>{live.length?'Visit your library':'Find your first words'}</Button></div>{/if}
 {:else if tab==='Library'}
 {#if detail}<Cover title={collection?.title||'Your own words'} subtitle={detailItems.length+' words to keep'} color={starters.findIndex((s:any)=>s.id===detail)} large/><div class="section-title"><h3>Your items</h3><button class="text-button" onclick={()=>navigate('Discover')}>Add items</button></div><List>{#each detailItems as item}<Row title={item.title} subtitle={item.learned?'Learned · '+new Date(item.due).toLocaleDateString():'Step '+item.step} onclick={()=>begin([item])}><StepDots step={item.learned?5:item.step}/></Row><button class="text-button" onclick={()=>void remove(item)}>Remove {item.title}</button>{/each}</List>{#if detailItems.length}<Button onclick={()=>begin(detailItems)}>Start practice</Button>{:else}<p>Nothing here yet.</p>{/if}
 {:else}<h3 class="section-title">Start here</h3><div class="covers">{#each starters as s,i}<Cover title={s.title} subtitle={s.subtitle} color={i} onclick={()=>void addStarter(s)}/>{/each}</div><div class="section-title"><h3>Yours</h3><button class="text-button" onclick={()=>navigate('Discover')}>+ Add</button></div><List>{#each [...new Set(live.map(i=>i.collection))] as id}{@const items=live.filter(i=>i.collection===id)}<Row title={starters.find((s:any)=>s.id===id)?.title||'Your own words'} subtitle={items.filter(i=>i.learned).length+' of '+items.length+' learned'} onclick={()=>detail=id}><StepDots step={Math.round(items.reduce((n,i)=>n+(i.learned?4:i.step-1),0)/items.length)+1}/></Row>{/each}</List>{#if !live.length}<p>Your library starts with one small choice.</p>{/if}{/if}
 {:else if tab==='Discover'}
 <div class="stack"><div class="covers">{#each [['verse','Add verses'],['own','Your own text'],['documents','Catechisms & creeds']] as [id,label]}<Button secondary={addMode!==id} onclick={()=>{addMode=id;found=[]}}>{label}</Button>{/each}</div>
 {#if addMode==='verse'}<label>Translation<select bind:value={translation}><option>BSB</option><option>KJV</option><option>WEB</option></select></label><label>Bible reference<input bind:value={reference} placeholder="Romans 8:28-30" onkeydown={e=>{if(e.key==='Enter')void search()}}/></label><Button onclick={()=>void search()} disabled={busy}>Find verses</Button>{#if found.length}<List>{#each found as item}<Row title={item.title} subtitle={item.text}/>{/each}</List><Button onclick={()=>void add(found)}>Add to library</Button>{/if}<small>Public-domain text · BSB, KJV and WEB. Available offline after first opening a book.</small>
 {:else if addMode==='own'}<label>Title or question<input bind:value={customTitle} maxlength={200}/></label><label>Text to remember<textarea bind:value={customText} maxlength={10000}></textarea></label><p>Only for you. Your own words are never shared.</p><Button onclick={()=>void own()}>Add your text</Button>
 {:else}<label>Browse<select bind:value={selectedDoc}><option value="">Choose a document</option>{#each documents as doc}<option value={doc.id}>{doc.title}</option>{/each}</select></label>{#if selectedDoc}{@const doc=documents.find((d:any)=>d.id===selectedDoc)}{#if doc}<List>{#each doc.items as item}<Row title={item.title} subtitle={item.text}/><button class="text-button" onclick={()=>void add([item],doc.id)}>Add {item.title}</button>{/each}</List>{/if}{/if}{/if}</div>
 {:else if tab==='Account'}
 <div class="stack"><label>Display name<input bind:value={data.settings.name} onchange={()=>void save()} maxlength={80}/></label><label>Appearance<select bind:value={data.settings.theme} onchange={()=>void save()}><option value="system">System</option><option value="light">Light</option><option value="dark">Dark</option></select></label><label>Weekly rhythm<select bind:value={data.settings.goal} onchange={()=>void save()}>{#each [3,4,5,7] as n}<option value={n}>{n} days a week</option>{/each}</select></label><label>Reminder time<input type="time" bind:value={data.settings.reminderTime} onchange={()=>void save()}/></label><label>Time zone<input bind:value={data.settings.timeZone} onchange={()=>void save()}/></label>
 <h3>Your account</h3>{#if account}<p>Signed in. Your words travel with you.</p><Button secondary onclick={()=>void signout()}>Sign out</Button>{:else}<p>Everything works on this device without an account. Sign in to keep your practice across devices.</p><Button onclick={()=>void signup()} disabled={busy}>Create account with a passkey</Button><Button secondary onclick={()=>void signin()} disabled={busy}>Sign in with a passkey</Button>{#if config.google}<Button secondary onclick={()=>location.href='/api/auth/google'}>Continue with Google</Button>{/if}<label>One-time recovery code<input bind:value={recoverInput} autocomplete="off"/></label><Button secondary onclick={()=>void recover()} disabled={busy||!recoverInput}>Use recovery code</Button>{/if}
 <h3>Gentle reminders</h3><p>One quiet invitation when you have words due, never after you’ve practiced. On iPhone, use Share → Add to Home Screen, then open By Heart there.</p><Button secondary onclick={()=>void (data.settings.pushEnabled?disablePush():enablePush())}>{data.settings.pushEnabled?'Disable reminders':'Enable reminders'}</Button>{#if data.settings.pushEnabled}<Button secondary onclick={()=>void attempt(async()=>{await api('/push/test',{});message='Test notification sent.'})}>Send test notification</Button>{/if}
 <Button secondary onclick={()=>void exportData()}>Export your data</Button>{#if account}<Button secondary onclick={()=>confirmDelete=true}>Delete account</Button>{/if}<small>By Heart · no ads, analytics or trackers. Public-domain Scripture and historic confessions. Figtree and Literata fonts, SIL OFL.</small></div>
 {:else if tab==='Gallery'}<div class="gallery"><Button>Primary button</Button><Button secondary>Secondary button</Button><StepDots step={3}/><WeekDots days={data.settings.days}/><Cover title="The Gospel in 10 verses" subtitle="10 verses" color={0} large/><Row title="John 3:16" subtitle="Step 2"><StepDots step={2}/></Row><VerseText words={['For','God','so','loved','the','world.']} mask={[false,true,false,true,true,false]} index={2}/><Keyboard onkey={()=>{}} onpeek={()=>{}}/></div>{/if}
 </section><TabBar active={tab} onchange={navigate}/>
{/if}
{#if recovery}<Sheet title="Your one-time recovery code"><p>Save this somewhere safe. It is shown once and lets you sign in on a new device. Using it replaces it with a new code.</p><code data-testid="recovery-code">{recovery}</code><Button onclick={()=>recovery=''}>I saved my code</Button></Sheet>{/if}
{#if confirmDelete}<Sheet title="Delete your account?" close={()=>confirmDelete=false}><p>Your synced items, passkeys, reminders and review history will be permanently deleted. Practice on this device stays here.</p><Button onclick={()=>void deleteAccount()}>Yes, delete account</Button><Button secondary onclick={()=>confirmDelete=false}>Keep account</Button></Sheet>{/if}
{#if welcome}<Sheet title="Welcome back."><p>No catching up. Start with three familiar words today, and we’ll gently make room for more over the next week.</p><Button onclick={()=>{data.settings.returnStart=today();welcome=false;void save()}}>A fresh start</Button></Sheet>{/if}
</main>
